<script lang="ts">
  import {onMount} from 'svelte';import {listen} from '@tauri-apps/api/event';import {rpc,errorText} from '../lib/api';import {newTab,selectRelative,afterClose,addressUrl,shortcutAction,type BrowserTab} from '../lib/browser-tabs';import Icon from './Icon.svelte';
  let {id,active,geometry,modal,requestDownload,openDownloads,downloadCount=0}:{id:string;active:boolean;geometry:string;modal:boolean;requestDownload:(url:string)=>void;openDownloads:()=>void;downloadCount?:number}=$props();
  let area:HTMLDivElement;let addressInput:HTMLInputElement;let findInput=$state<HTMLInputElement>();let tabs=$state<BrowserTab[]>([]);let selected=$state('');let address=$state('');let error=$state('');let findOpen=$state(false);let term=$state('');let alive=true;let synced=Promise.resolve();let findTimer:ReturnType<typeof setTimeout>;
  const current=$derived(tabs.find(t=>t.id===selected));
  function patch(tabId:string,values:Partial<BrowserTab>){tabs=tabs.map(t=>t.id===tabId?{...t,...values}:t);}
  function sync(){if(!area)return;const r=area.getBoundingClientRect();const args={x:Math.round(r.x),y:Math.round(r.y),width:Math.round(r.width),height:Math.round(r.height)};const target=current?.ready?current:tabs.find(t=>t.ready);if(!target)return;const snapshot=[{id:target.id,...args,visible:active&&!modal&&target.id===selected&&(!!target.url||!!target.popupParent)&&r.width>5&&r.height>5}];synced=synced.catch(()=>{}).then(async()=>{if(!alive)return;for(const b of snapshot)if(tabs.some(t=>t.id===b.id))await rpc('browser_bounds',b);}).catch(e=>{if(alive)error=errorText(e);});}
  $effect(()=>{geometry;active;modal;selected;tabs.map(t=>`${t.ready}${t.url}`).join();findOpen;requestAnimationFrame(sync);});
  async function action(action:string,url?:string){if(!current?.ready)return;try{await rpc('browser_action',{id:current.id,action,...(url?{url}:{})});}catch(e){error=errorText(e);}}
  async function add(url='',tabId:string=crypto.randomUUID(),popupParent?:string){if(tabs.length>=24){error='This window supports up to 24 tabs.';if(popupParent)void rpc('browser_action',{id:tabId,action:'close'}).catch(()=>{});return;}const tab=newTab(tabId,url,popupParent);tabs=[...tabs,tab];selected=tabId;address=url==='about:blank'?'':url;error='';try{await rpc('browser_open',{id:tabId,owner:id,url,...(popupParent?{popupParent}:{})});if(!alive||!tabs.some(t=>t.id===tabId)){await rpc('browser_action',{id:tabId,action:'close'});return;}patch(tabId,{ready:true});sync();if(!url)addressInput?.focus();}catch(e){error=errorText(e);patch(tabId,{title:'Could not open tab',loading:false});}}
  function select(tabId:string){selected=tabId;address=tabs.find(t=>t.id===tabId)?.url||'';findOpen=false;error='';sync();if(current?.url)void action('focus');else addressInput?.focus();}
  async function closeTab(tabId:string){const next=afterClose(tabs.map(t=>t.id),selected,tabId);const wasReady=tabs.find(t=>t.id===tabId)?.ready;tabs=tabs.filter(t=>t.id!==tabId);selected=next;address=tabs.find(t=>t.id===next)?.url||'';if(wasReady)try{await rpc('browser_action',{id:tabId,action:'close'});}catch(e){error=errorText(e);}if(!tabs.length&&alive)await add();sync();}
  function navigate(){try{const url=addressUrl(address);if(!url)return;address=url;if(current){patch(current.id,{url,loading:true});void action('navigate',url);sync();}}catch(e){error=errorText(e);}}
  async function find(action='start'){if(!current?.ready)return;try{await rpc('browser_find',{id:current.id,term,action});}catch(e){error=errorText(e);}}
  function shortcut(actionName:string){if(!active||modal)return;if(actionName==='new')void add();else if(actionName==='close'&&selected)void closeTab(selected);else if(actionName==='next'||actionName==='previous')select(selectRelative(tabs.map(t=>t.id),selected,actionName==='next'?1:-1));else if(actionName.startsWith('tab-')){const n=Number(actionName.slice(4));const tab=n===8?tabs.at(-1):tabs[n];if(tab)select(tab.id);}else if(actionName==='address'){addressInput?.focus();addressInput?.select();}else if(actionName==='downloads')openDownloads();else if(actionName==='save')requestDownload(current?.url||address);else if(actionName==='find'){findOpen=true;requestAnimationFrame(()=>findInput?.focus());}else void action(actionName);}
  onMount(()=>{
    const off:Array<()=>void>=[];alive=true;
    const key=(e:KeyboardEvent)=>{if(!active||modal)return;const command=shortcutAction(e.key,e.ctrlKey,e.shiftKey,e.altKey);if(command){e.preventDefault();shortcut(command);}};window.addEventListener('keydown',key);
    void(async()=>{try{
      off.push(await listen<{id:string;title:string}>('browser-title',e=>patch(e.payload.id,{title:e.payload.title||'New tab'})));
      off.push(await listen<{id:string;url:string;loading:boolean}>('browser-page',e=>{const p=e.payload;if(!tabs.some(t=>t.id===p.id))return;const url=p.url==='about:blank'?'':p.url;patch(p.id,{url,loading:p.loading});if(selected===p.id&&document.activeElement!==addressInput)address=url;}));
      off.push(await listen<{id:string;data:string}>('browser-favicon',e=>patch(e.payload.id,{favicon:e.payload.data})));
      off.push(await listen<{owner:string;id:string;parent:string;url:string}>('browser-new-tab',e=>{if(e.payload.owner===id&&alive)void add(e.payload.url,e.payload.id,e.payload.parent);}));
      off.push(await listen<{owner:string;action:string}>('browser-shortcut',e=>{if(e.payload.owner===id)shortcut(e.payload.action);}));
      if(!alive){off.forEach(f=>f());return;}await add();
    }catch(e){error=errorText(e);}})();
    const observer=new ResizeObserver(sync);observer.observe(area);window.addEventListener('resize',sync);
    return()=>{alive=false;clearTimeout(findTimer);observer.disconnect();window.removeEventListener('resize',sync);window.removeEventListener('keydown',key);off.forEach(f=>f());const ids=tabs.map(t=>t.id);void synced.finally(async()=>{for(const tabId of ids)await rpc('browser_action',{id:tabId,action:'close'}).catch(()=>{});});};
  });
</script>
<div class="app-column browser-app">
  <div class="browser-tabs" role="tablist" aria-label="Browser tabs">{#each tabs as tab(tab.id)}<div class="browser-tab" class:active={selected===tab.id}><button role="tab" aria-selected={selected===tab.id} onclick={()=>select(tab.id)} title={tab.title}>{#if tab.loading}<span class="spinner tiny"></span>{:else if tab.favicon}<img src={tab.favicon} alt=""/>{:else}<Icon name="browser" size={14}/>{/if}<span>{tab.title}</span></button><button class="tab-close" aria-label={`Close ${tab.title}`} onclick={()=>closeTab(tab.id)}><Icon name="close" size={12}/></button></div>{/each}<button class="icon-button" title="New tab (Ctrl+T)" onclick={()=>add()}><Icon name="plus" size={17}/></button></div>
  <form class="toolbar browser-toolbar" onsubmit={e=>{e.preventDefault();navigate();}}><button type="button" class="icon-button" title="Back (Alt+Left)" onclick={()=>action('back')}><Icon name="back" size={18}/></button><button type="button" class="icon-button" title="Forward (Alt+Right)" onclick={()=>action('forward')}><Icon name="forward" size={18}/></button><button type="button" class="icon-button" title={current?.loading?'Stop':'Reload (Ctrl+R)'} onclick={()=>action(current?.loading?'stop':'reload')}><Icon name={current?.loading?'stop':'refresh'} size={17}/></button><div class="address-field"><Icon name={address.startsWith('https:')?'lock':'browser'} size={15}/><input bind:this={addressInput} aria-label="Website address" bind:value={address} placeholder="Search or enter an HTTPS address"/></div><button type="button" class="icon-button" title="Send a direct URL to server" onclick={()=>requestDownload(current?.url||address)}><Icon name="link" size={18}/></button><button type="button" class="browser-downloads" title="Downloads (Ctrl+J)" onclick={openDownloads}><Icon name="downloads" size={19}/>{#if downloadCount}<span>{downloadCount}</span>{/if}</button></form>
  {#if findOpen}<form class="browser-find" onsubmit={e=>{e.preventDefault();void find('next');}}><input bind:this={findInput} aria-label="Find on page" placeholder="Find on page" bind:value={term} oninput={()=>{clearTimeout(findTimer);findTimer=setTimeout(()=>find(),150);}}/><button type="button" onclick={()=>find('previous')}>Previous</button><button>Next</button><button type="button" aria-label="Close find" onclick={()=>{findOpen=false;void find('stop');}}><Icon name="close" size={14}/></button></form>{/if}
  {#if error}<div class="error-box">{error}</div>{/if}
  <div class="browser-native-area" bind:this={area}>{#if !current?.url&&!current?.popupParent}<div class="browser-new-page"><Icon name="browser" size={44}/><h2>A window to the web</h2><p>Pages run locally in Microsoft Edge WebView2.</p><p>Downloads always ask for a remote destination.</p><button onclick={()=>{addressInput?.focus();}}>Search or enter an address</button></div>{:else if !active||modal}<div class="empty-state"><Icon name="browser" size={32}/><p>Your page is open behind the workspace</p><small>Focus this window to continue browsing.</small></div>{:else if !current?.ready}<div class="empty-state"><span class="spinner"></span><p>Starting Microsoft Edge WebView2…</p></div>{/if}</div>
</div>
<style>
  .browser-tabs{display:flex;align-items:center;gap:3px;padding:5px 7px 0;background:color-mix(in srgb,var(--window),black 14%);overflow-x:auto;flex-shrink:0;min-height:35px}.browser-tab{display:flex;align-items:center;min-width:90px;max-width:190px;flex:1;border-radius:7px 7px 0 0;border:1px solid transparent}.browser-tab.active{background:var(--window);border-color:var(--line);border-bottom-color:var(--accent)}.browser-tab>button:first-child{display:flex;align-items:center;gap:7px;min-width:0;flex:1;padding:8px;border:0;background:transparent;text-align:left;font-size:12px}.browser-tab span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.browser-tab img{width:16px;height:16px}.tab-close{border:0;background:transparent;padding:5px;margin-right:3px}.browser-find{display:flex;gap:5px;padding:5px 10px;border-bottom:1px solid var(--line)}.browser-find input{flex:1}.browser-new-page{height:100%;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:var(--muted)}.browser-new-page h2{color:var(--text);margin:0}.browser-new-page p{margin:0}.browser-downloads{display:flex;align-items:center;gap:4px}.browser-downloads span{border-radius:9px;background:var(--accent);color:#102333;min-width:18px;font-size:11px;padding:2px}
</style>
